local L = select(2, ...).L

L["binding.birch.description"] = "Pale and papery, with dark flecks. Likely the only book here that would float."
L["binding.birch.name"] = "Birch Bark"
L["binding.buckram.description"] = "Stiff sea-green cloth with cream rules. Spray beads up and rolls straight off."
L["binding.buckram.name"] = "Sea-Green Buckram"
L["binding.field.description"] = "Plain brown leather, made to be rained on, and it usually is."
L["binding.field.name"] = "Field Leather"
L["binding.level10.description"] = "Lighter, softer hide, worn smooth at the corners by a few seasons of wet thumbs."
L["binding.level10.name"] = "Tanned Hide"
L["binding.level20.description"] = "Deep blue leather with silver rules, the colour of a harbour at dusk."
L["binding.level20.name"] = "Tidewater Blue"
L["binding.level30.description"] = "Dark green leather, gilt the colour of dry reeds, and a faint smell of riverbank."
L["binding.level30.name"] = "Reed Green"
L["binding.level40.description"] = "Deep red leather and heavy gilt. Fish blood barely shows on it."
L["binding.level40.name"] = "Oxblood"
L["binding.level50.description"] = "Slate-grey leather with silver tooling, for the days nobody else goes out."
L["binding.level50.name"] = "Storm Grey"
L["binding.level60.description"] = "Near-black leather and bright gold. About as fine as an angler's book gets."
L["binding.level60.name"] = "Nat's Own"
L["binding.sharkskin.description"] = "Rough grey hide with silver tooling. It won't slip out of a wet hand."
L["binding.sharkskin.name"] = "Sharkskin"
L["crest.alterac.description"] = "A broken tower on a cold peak. The kingdom is gone. The streams are still good."
L["crest.alterac.name"] = "The Broken Tower"
L["crest.arathi.description"] = "Old standing stones on the highland grass, older than anyone who argues about them."
L["crest.arathi.name"] = "The Standing Stones"
L["crest.ashenvale.description"] = "A wisp drifting between dark trees. The forest notices every angler who stays too long."
L["crest.ashenvale.name"] = "The Wisp"
L["crest.azshara.description"] = "A column of an old empire, the sea climbing it. Something still swims in those ruins."
L["crest.azshara.name"] = "The Fallen Column"
L["crest.badlands.description"] = "A stone arch the wind took ten thousand years to finish. Bring your own water."
L["crest.badlands.name"] = "The Stone Arch"
L["crest.barrens.description"] = "A flat-topped tree on the dry plains. Every oasis out there is somebody's favourite spot."
L["crest.barrens.name"] = "The Acacia"
L["crest.blackrock.description"] = "A black mountain with fire in its cracks and chains across its gate. Fish the lava pools at your own risk."
L["crest.blackrock.name"] = "The Black Spire"
L["crest.blastedlands.description"] = "A gate of black stone with green fire in it. Nobody fishes there for the view."
L["crest.blastedlands.name"] = "The Burning Gate"
L["crest.burningsteppes.description"] = "A mountain on fire under an ash sky. The water is warm enough to cook in."
L["crest.burningsteppes.name"] = "The Burning Peak"
L["crest.darkshore.description"] = "A crescent over grey water, for anglers who fish after dark."
L["crest.darkshore.name"] = "The Crescent"
L["crest.darnassus.description"] = "A well glowing silver under a great tree. The lake around it holds the city's fish."
L["crest.darnassus.name"] = "The Silver Well"
L["crest.deadwind.description"] = "A tall tower in a dead valley. The pools are quiet. Too quiet, some say, and leave."
L["crest.deadwind.name"] = "The Lonely Tower"
L["crest.desolace.description"] = "A great horned skull from an old graveyard. The coast is kinder than the inland."
L["crest.desolace.name"] = "The Horned Skull"
L["crest.dunmorogh.description"] = "Curled horns over a snowfield. The rams up there have opinions about strangers."
L["crest.dunmorogh.name"] = "The Ram"
L["crest.durotar.description"] = "A scorpid on red earth. The coast is better company than the scorpids."
L["crest.durotar.name"] = "The Scorpid"
L["crest.duskwood.description"] = "Two eyes between black trees. Anglers there keep the lantern lit and the line short."
L["crest.duskwood.name"] = "Eyes in the Wood"
L["crest.dustwallow.description"] = "A lantern left burning on a fisherman's hut in the marsh fog."
L["crest.dustwallow.name"] = "The Lantern"
L["crest.easternplague.description"] = "A small chapel holding its light against the blight. Good water lies beside it."
L["crest.easternplague.name"] = "The Chapel"
L["crest.elwynn.description"] = "The first lake most anglers ever saw, and the oak they sat under."
L["crest.elwynn.name"] = "The Old Oak"
L["crest.felwood.description"] = "A twisted tree with green fire in its veins. Wash every catch from there. Twice."
L["crest.felwood.name"] = "The Tainted Tree"
L["crest.feralas.description"] = "Water falling between the giant trees, for anglers who take the long way."
L["crest.feralas.name"] = "The Falls"
L["crest.hillsbrad.description"] = "Three apples from the foothill orchards. The trout below the mill are fat on windfalls."
L["crest.hillsbrad.name"] = "Three Apples"
L["crest.hinterlands.description"] = "Great feathers from the wild hills, where big birds nest above the rivers."
L["crest.hinterlands.name"] = "Three Feathers"
L["crest.hyjal.description"] = "A green shoot rising out of old embers. The mountain is mending, and its streams with it."
L["crest.hyjal.name"] = "The Sapling"
L["crest.ironforge.description"] = "An anvil before the mountain's forge. There is a lake under there, and dwarves fish it."
L["crest.ironforge.name"] = "The Anvil"
L["crest.lochmodan.description"] = "A dam holding back a highland lake. Dwarves built it to last, and it has."
L["crest.lochmodan.name"] = "The Great Dam"
L["crest.lordamere.description"] = "A wooded island on a wide grey lake, a boat drawn up on its shore. Quiet water, and plenty of it."
L["crest.lordamere.name"] = "The Lake Isle"
L["crest.moonglade.description"] = "Antlers over a still lake, under the moon. A quiet place, kept quiet on purpose."
L["crest.moonglade.name"] = "The Antlers"
L["crest.mulgore.description"] = "A carved totem on the long grass plains, where the streams run clear from the hills."
L["crest.mulgore.name"] = "The Totem"
L["crest.orgrimmar.description"] = "A spiked gate in a red canyon. The city's pools are deeper than they look."
L["crest.orgrimmar.name"] = "The Spiked Gate"
L["crest.redridge.description"] = "Three red peaks standing in a mountain lake, and every one of them reflected."
L["crest.redridge.name"] = "Three Peaks"
L["crest.riverglades.description"] = "A barge on a winding river between green hills. Trade comes by water there, and so do fish."
L["crest.riverglades.name"] = "The Barge"
L["crest.searinggorge.description"] = "A crucible pouring molten gold. Fishing there means lava, so bring patience and a long rod."
L["crest.searinggorge.name"] = "The Crucible"
L["crest.shendralas.description"] = "An open book on a broken pedestal, kept by people who never stopped reading."
L["crest.shendralas.name"] = "The Open Tome"
L["crest.silithus.description"] = "A scarab on desert sand. The lakes there are small and suspicious."
L["crest.silithus.name"] = "The Scarab"
L["crest.silverpine.description"] = "Silver pines on a dark lake shore. Something howls out there most nights."
L["crest.silverpine.name"] = "Silver Pines"
L["crest.stonetalon.description"] = "A great talon gripping a stone. Mountain water, cold and quick."
L["crest.stonetalon.name"] = "The Talon"
L["crest.stormwind.description"] = "White walls and a gate over the canals. The city fishes its own waterways, politely."
L["crest.stormwind.name"] = "The White Keep"
L["crest.stranglethorn.description"] = "A fish leaping clear of the jungle surf, as if it heard about the contest."
L["crest.stranglethorn.name"] = "The Leap"
L["crest.swampofsorrows.description"] = "A temple roof breaking the swamp water. What is under it stays under it."
L["crest.swampofsorrows.name"] = "The Drowned Shrine"
L["crest.tanaris.description"] = "A desert sun over the only shade for miles: the shoreline."
L["crest.tanaris.name"] = "The Desert Sun"
L["crest.teldrassil.description"] = "A tree so tall its crown is in the stars. Its roots drink from very old water."
L["crest.teldrassil.name"] = "The Starlit Crown"
L["crest.thousandneedles.description"] = "Stone needles rising from the flats. Fish in their shadows, and keep your hat on."
L["crest.thousandneedles.name"] = "The Needles"
L["crest.thunderbluff.description"] = "A high mesa with a tent on top. The pools below catch the falls, and the fish with them."
L["crest.thunderbluff.name"] = "The Mesa"
L["crest.tirisfal.description"] = "A bat across a sickly moon. Even the fish there look a little tired."
L["crest.tirisfal.name"] = "The Bat"
L["crest.undercity.description"] = "A broken crown over green canals. The court is gone. The canals still hold fish."
L["crest.undercity.name"] = "The Broken Crown"
L["crest.ungoro.description"] = "A footprint the size of a rowing boat. The crater has bigger worries than fish."
L["crest.ungoro.name"] = "The Footprint"
L["crest.veiledsea.description"] = "A ship half lost in a bank of sea fog. Out here the fish come up from very deep, and so does everything else."
L["crest.veiledsea.name"] = "The Fog Bank"
L["crest.westernplague.description"] = "A crow on a dead tree over empty fields. The farmers left. The fish did not."
L["crest.westernplague.name"] = "The Crow"
L["crest.westfall.description"] = "Sails turning over the coast road. The sea is closer than the farmers admit."
L["crest.westfall.name"] = "The Windmill"
L["crest.wetlands.description"] = "A harbour's anchor, hauled up from the mud. Still smells faintly of it."
L["crest.wetlands.name"] = "The Anchor"
L["crest.winterspring.description"] = "A snowflake over still water, where ice fishing is real fishing."
L["crest.winterspring.name"] = "The Frost"
L["crest.zephras.description"] = "An island floating on cloud, its ship tied to the stone. The water is a long way down."
L["crest.zephras.name"] = "The Floating Isle"
L["family.1.name"] = "Mud Snapper"
L["family.2.name"] = "Catfish"
L["family.3.name"] = "Yellowtail"
L["family.4.name"] = "Redgill"
L["family.5.name"] = "Salmon"
L["family.6.name"] = "Lobster"
L["family.7.name"] = "Mightfish"
L["legend.19803.blurb"] = "Most anglers only ever see its wake. This one slowed down long enough to be landed."
L["legend.19803.title"] = "Racer-Chaser"
L["legend.19805.blurb"] = "Far too handsome for a contest table, and it seems to know it."
L["legend.19805.title"] = "Keefer's Rival"
L["legend.19806.blurb"] = "Carries itself like royalty, and fights as if it had a crown to lose."
L["legend.19806.title"] = "Queen-Catcher"
L["line.uncaughtjunk.text"] = "The plinth is dusted and ready. The exhibit is late."
L["line.uncaughtlegend.text"] = "Some fish are only caught once in a long while. This page waits for one."
L["line.uncaughttreasure.text"] = "Something sealed, not yet found."
L["line.unchartedwaters.text"] = "Uncharted waters. No map of these yet."
L["species.12238.blurb"] = "Broad, slow and grey as the coast it's named for. It makes a better stew than a first impression."
L["species.12238.riddle"] = "Grey water under old trees on a moonlit coast, or far south in the desert."
L["species.13422.blurb"] = "Armourers pay well for the scales. The eel disagrees with the arrangement."
L["species.13422.riddle"] = "A writhing swarm in deep sea water off the wilder coasts."
L["species.13754.blurb"] = "Heavy enough that some anglers fish it sitting down."
L["species.13754.riddle"] = "Open sea off the far coasts, deep enough for the heavy ones."
L["species.13755.blurb"] = "Arrives with the frost. More arms than an angler can reasonably untangle."
L["species.13755.riddle"] = "Warm shores, once the year turns cold."
L["species.13756.blurb"] = "Turns up with the long days and leaves with the first cold wind."
L["species.13756.riddle"] = "Warm shores in the warm half of the year."
L["species.13757.blurb"] = "Tingles. Don't lick it."
L["species.13757.riddle"] = "A crackle in far, wild waters, from sunrise into the late evening."
L["species.13758.blurb"] = "Gills like embers. Bites like it means it."
L["species.13758.riddle"] = "Inland waters of the wilder lands, by day or by night."
L["species.13759.blurb"] = "Feeds by starlight. Anglers who want it learn to like the dark."
L["species.13759.riddle"] = "Wild waters far from the gentle shores, after the sun goes down."
L["species.13760.blurb"] = "Rises with the sun and keeps late hours. Nobody knows where it goes before dawn."
L["species.13760.riddle"] = "Far rivers and lakes, warm or cold, while the sun is up."
L["species.13888.blurb"] = "Pinches first, asks questions never."
L["species.13888.riddle"] = "Deep rocky waters at the far edges of the world."
L["species.13889.blurb"] = "Pale as frost. Best eaten the day it's caught, which is rarely possible."
L["species.13889.riddle"] = "The farthest waters there are, from frozen lakes to scorched hills."
L["species.13890.blurb"] = "Wears its armour on the outside and its temper on the inside. Bring a heavier knife."
L["species.13890.riddle"] = "Something heavy in the farthest waters, after the sun goes down."
L["species.13893.blurb"] = "The big cousin. You will need both hands and probably a friend."
L["species.13893.riddle"] = "Deep water off a far and forgotten coast."
L["species.1467.blurb"] = "A cheerful little fish with no idea how many cooks are waiting for it."
L["species.1467.riddle"] = "A calm hill lake in settled farming country."
L["species.16967.blurb"] = "Big, quick and good eating. Most are caught as a favour for someone else, which seems a waste."
L["species.16967.riddle"] = "A broad river through wet, overgrown forest in the far west."
L["species.16968.blurb"] = "Hits the bait like it's been waiting all day for an argument."
L["species.16968.riddle"] = "A bleak, grey shore on a dry and empty western coast."
L["species.16969.blurb"] = "That sail is for show, and it knows it. Fights like it has an audience."
L["species.16969.riddle"] = "Warm jungle shallows, where the sea runs right up to the trees."
L["species.16970.blurb"] = "Bright as a jungle bird and twice as much trouble on the line."
L["species.16970.riddle"] = "Warm, murky shallows where a swamp meets the sea."
L["species.19807.blurb"] = "Tournament fish. Tastes of victory, or at least of a long afternoon trying."
L["species.19807.riddle"] = "Only while the jungle's great contest is on."
L["species.19975.blurb"] = "Smells exactly as the name promises. Somebody, somewhere, still wants a dozen."
L["species.19975.riddle"] = "Churning brown water, deep in the steaming jungle."
L["species.21071.blurb"] = "Smells like the hills it swims past."
L["species.21071.riddle"] = "Small schools in the hills and forests, smelling faintly of herbs."
L["species.21153.blurb"] = "The sage grew up."
L["species.21153.riddle"] = "Bigger herb-scented schools, in snowy hills and steaming jungle."
L["species.251524.blurb"] = "New to these waters, and nobody's quite sure how it got here."
L["species.251524.riddle"] = "Bright new schools on a quiet lake in the eastern hills."
L["species.4603.blurb"] = "Fast, bright, and very pleased with itself."
L["species.4603.riddle"] = "Salt coasts north and south, on both sides of the sea."
L["species.6289.blurb"] = "It bites anything, including, once, a gnome's boot."
L["species.6289.riddle"] = "Lazy rivers in the lands where heroes begin."
L["species.6291.blurb"] = "Small, bright and everywhere. Every angler's book starts here, and nobody admits how many they threw back."
L["species.6291.riddle"] = "The very first thing to tug a beginner's line, in the gentlest waters of all."
L["species.6299.blurb"] = "Looks bad, smells worse, cooks into something a raptor would eat."
L["species.6299.riddle"] = "Tired, grey water in the gloomy north, on both sides of the sea."
L["species.6303.blurb"] = "Slippery enough to earn the name. Fries up better than it has any right to."
L["species.6303.riddle"] = "Shallow coasts, where new adventurers wade."
L["species.6308.blurb"] = "All whiskers and grudge. It sulks on the bottom until it decides to fight."
L["species.6308.riddle"] = "Murky rivers on both sides of the sea."
L["species.6317.blurb"] = "Named by dwarves, who name everything after how it behaves when you try to hold it."
L["species.6317.riddle"] = "Cold highland lake water, in dwarf country."
L["species.6358.blurb"] = "Alchemists want the oil. Cooks want nothing to do with it."
L["species.6358.riddle"] = "A school that leaves a slick on coastal waters."
L["species.6359.blurb"] = "Warm to the touch, even out of the water."
L["species.6359.riddle"] = "Swirling schools the colour of embers, off coasts north and south."
L["species.6361.blurb"] = "The colours fade within an hour of landing. Look quickly."
L["species.6361.riddle"] = "Open coast, a little further from shore than you're used to."
L["species.6362.blurb"] = "Stubborn on the line, sweet on the plate."
L["species.6362.riddle"] = "Sea coasts from the misty north to the hot south, where the bottom drops away."
L["species.6458.blurb"] = "Less a fish than a warning about the water. Wash it twice, then think again."
L["species.6458.riddle"] = "Fouled water where goblins drill the parched hills and plains."
L["species.6522.blurb"] = "Eat one at your own risk. No two anglers who did tell the same story about the hour after."
L["species.6522.riddle"] = "Strange schools out on the dry plains, where the water itself seems unwell."
L["species.8365.blurb"] = "The head really does shine. No, it isn't mithril. Stop asking the smith."
L["species.8365.riddle"] = "Lakes and rivers in rougher country, from deep forest to bare desert."
L["sub.13874.plaque"] = "Too heavy to float and too heavy to carry far. Someone tried both."
L["sub.13875.plaque"] = "Bound in iron and locked besides. Whatever's inside was worth the worry."
L["sub.13881.plaque"] = "Too greedy to stop eating, and too full to swim away."
L["sub.13918.plaque"] = "Reinforced, locked, and sunk anyway. Some cargo never gets a break."
L["sub.20708.plaque"] = "Sealed so tight the water never got in. Neither, it seems, did the owner."
L["sub.21113.plaque"] = "Watertight, as promised. Nobody promised it would float."
L["sub.21150.plaque"] = "The iron held. The ship it came off did not."
L["sub.21162.plaque"] = "Swollen, slick and full of someone else's luck. Wash your hands after."
L["sub.21164.plaque"] = "Stubborn to the last. It gave up what it swallowed only to a knife."
L["sub.21228.plaque"] = "Bound in mithril. Whoever packed it expected trouble, and got some."
L["sub.21243.plaque"] = "Big enough to swallow a purse whole, and it did."
L["sub.6297.plaque"] = "Donated by the water. Owner unknown, and preferably staying that way."
L["sub.6301.plaque"] = "Belonged to someone who drove wagons. Still looks like it's waiting for one."
L["sub.6307.plaque"] = "The ink ran long ago. The cork, to its credit, held."
L["sub.6351.plaque"] = "Dropped once, by the look of it, and then again for good measure."
L["sub.6352.plaque"] = "Packed for a dry voyage. It did not get one."
L["sub.6353.plaque"] = "Small enough to lose over the side. Someone proved it."
L["sub.6354.plaque"] = "Small, locked, and more trouble to open than it ever was to carry."
L["sub.6355.plaque"] = "Built to survive anything. The sea has been testing the claim."
L["sub.6356.plaque"] = "Someone locked it, someone sank it, and neither came back for it."
L["sub.6357.plaque"] = "Sealed tight against the water. The water was patient."
L["sub.6455.plaque"] = "Where the wagon went is still under investigation."
L["sub.6456.plaque"] = "Please do not touch the exhibit."
L["sub.6457.plaque"] = "A gnome would call this 'nearly working'."
L["sub.6643.plaque"] = "A small fish with a large appetite and no sense of what counts as food."
L["sub.6645.plaque"] = "It bit something far too big to swallow, and swallowed it anyway."
L["sub.6647.plaque"] = "Fed off the bottom, where everyone's dropped things end up."
L["sub.6717.plaque"] = "A tinker's spare parts, dropped over the side mid-job. He insists the boat leaked first."
L["sub.6718.plaque"] = "Parts for a clockwork duck decoy, the kind that explodes. Kept well away from the real ducks."
L["sub.7973.plaque"] = "Says nothing about what's inside. Open it anyway; sometimes it's a pearl."
L["sub.8366.plaque"] = "Ate something shiny. Possibly even mithril, this time."
L["title.complete.junk.text"] = "Collector of Boots"
L["title.complete.ledger.text"] = "Angler of Azeroth"
L["title.complete.treasure.text"] = "Keeper of Lost Cargo"
L["title.complete.trophy.text"] = "Tipper of Scales"
L["title.complete.varieties.text"] = "Keeper of Every Colour"
L["title.level1.text"] = "Minnow"
L["title.level10.text"] = "Dabbler"
L["title.level20.text"] = "Line-Caster"
L["title.level30.text"] = "Fisher"
L["title.level40.text"] = "Old Salt"
L["title.level50.text"] = "Tide-Reader"
L["title.level60.text"] = "Nat's Peer"
L["title.prestige1.text"] = "Returning Tide"
L["title.prestige10.text"] = "High-Water Mark"
L["title.prestige5.text"] = "Undertow"
L["title.zonemaster.text"] = "Warden of {zone} Waters"
